import { z } from "zod";

/**
 * SFID (Snowflake 63-bit) represented as a decimal string in the application
 * layer. DB column: `BIGINT(20) NOT NULL`.
 *
 * Exactly 19 decimal digits — matches IDs generated by SfidService in 2024+
 * (41-bit relative timestamp from Twitter epoch 2010-11-04 × 2^22 produces
 * values in [1.6e18, 9.2e18] range).
 *
 * ref: docs/detailed-design/00-foundations/naming-and-db-conventions.md §2.1
 *      docs/technical-design/phase-1/P1-01-foundations.md §3.4
 */
export const SfidSchema = z.string().regex(/^\d{19}$/u, "SFID must be exactly 19 decimal digits");
export type Sfid = z.infer<typeof SfidSchema>;

export const SessionIdSchema = SfidSchema.brand<"SessionId">();
export type SessionId = z.infer<typeof SessionIdSchema>;

export const TurnIdSchema = SfidSchema.brand<"TurnId">();
export type TurnId = z.infer<typeof TurnIdSchema>;

export const MessageIdSchema = SfidSchema.brand<"MessageId">();
export type MessageId = z.infer<typeof MessageIdSchema>;

export const JobIdSchema = SfidSchema.brand<"JobId">();
export type JobId = z.infer<typeof JobIdSchema>;

export const GrantIdSchema = SfidSchema.brand<"GrantId">();
export type GrantId = z.infer<typeof GrantIdSchema>;

export const ToolAckIdSchema = SfidSchema.brand<"ToolAckId">();
export type ToolAckId = z.infer<typeof ToolAckIdSchema>;

// TenantSchema has been moved to ./tenant.ts (P1-01 refactor); re-exported
// here so legacy callers `import { TenantSchema } from '...common/ids'`
// keep compiling. New code should `import from '...common/tenant'`.
export { TenantSchema, type TenantId } from "./tenant";
